import "./divider.css";

export interface DividerProps {
  style: "solid" | "dashed" | "dots";
  spacing: "small" | "medium" | "large";
}

export function Divider({ style, spacing }: DividerProps) {
  return (
    <div className="p1-divider" data-style={style} data-spacing={spacing}>
      {style === "dots" ? (
        <div className="p1-divider__dots">
          {[0, 1, 2].map((i) => (
            <span key={i} className="p1-divider__dot" />
          ))}
        </div>
      ) : (
        <hr className="p1-divider__rule" />
      )}
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { Divider, type DividerProps } from "./divider";
export type { DividerProps };

export const DividerBlock: ComponentConfig<DividerProps> = {
  fields: {
    style: {
      type: "select",
      options: [
        { label: "Solid", value: "solid" },
        { label: "Dashed", value: "dashed" },
        { label: "Dots", value: "dots" },
      ],
    } as const,
    spacing: {
      type: "select",
      options: [
        { label: "Small", value: "small" },
        { label: "Medium", value: "medium" },
        { label: "Large", value: "large" },
      ],
    } as const,
  },
  defaultProps: { style: "solid", spacing: "medium" },
  render: Divider,
};

export const meta = defineMeta({
  title: 'Divider',
  description: 'Horizontal rule in solid, dashed, or dot styles with configurable vertical spacing; use to visually separate page sections.',
  categories: ["content"],
  published: true,
});

.p1-divider {
  margin-inline: auto;
  max-inline-size: var(--p1-container-default);
  padding-inline: var(--p1-space-lg);
}

.p1-divider[data-spacing="small"] { padding-block: var(--p1-space-sm); }
.p1-divider[data-spacing="medium"] { padding-block: var(--p1-space-lg); }
.p1-divider[data-spacing="large"] { padding-block: var(--p1-space-xl); }

.p1-divider__dots {
  display: flex;
  justify-content: center;
  gap: 0.625rem;
}

.p1-divider__dot {
  block-size: 0.375rem;
  inline-size: 0.375rem;
  border-radius: var(--p1-radius-pill);
  background: var(--p1-border);
}

.p1-divider__rule {
  margin: 0;
  border: 0;
  border-block-start: 1px solid var(--p1-border);
}

.p1-divider[data-style="dashed"] .p1-divider__rule {
  border-block-start-width: 2px;
  border-block-start-style: dashed;
}

